# 订单台账 · 全量基线样例清单（纯虚构示例，只演示格式）
# 全量迁移的唯一打包依据：本清单逐行 == 项目全部部署物。
# 首次注册项目时按"部署物构成"逐类清点生成草稿，逐行 review 定稿；
# 此后每轮增量把新增文件并入本清单（仅覆盖旧文件的不动）。
# 源根（示例）：D:\DemoRepo\out\production\OrderModule

# —— classbean：类（含内嵌类）+ 随包加载的 properties ——
com/engine/demo/order/cmd/OrderBoardCmd.class	=>	classbean/com/engine/demo/order/cmd/OrderBoardCmd.class
com/engine/demo/order/cmd/OrderBoardCmd$Range.class	=>	classbean/com/engine/demo/order/cmd/OrderBoardCmd$Range.class
com/engine/demo/order/cmd/OrderSummaryCmd.class	=>	classbean/com/engine/demo/order/cmd/OrderSummaryCmd.class
com/engine/demo/order/service/OrderBoardService.class	=>	classbean/com/engine/demo/order/service/OrderBoardService.class
com/engine/demo/order/service/impl/OrderBoardServiceImpl.class	=>	classbean/com/engine/demo/order/service/impl/OrderBoardServiceImpl.class
com/engine/demo/order/util/OrderConfig.class	=>	classbean/com/engine/demo/order/util/OrderConfig.class
com/engine/demo/order/util/OrderUtil.class	=>	classbean/com/engine/demo/order/util/OrderUtil.class
com/engine/demo/order/util/OrderUtil$Scope.class	=>	classbean/com/engine/demo/order/util/OrderUtil$Scope.class
com/web/config/order-config.properties	=>	classbean/com/web/config/order-config.properties

# —— mobile：页面与静态资源 ——
mobile/plugin/orderBoard/orderBoard.jsp	=>	mobile/plugin/orderBoard/orderBoard.jsp

# —— WEB-INF：安全白名单 XML（如有）——
WEB-INF/security/order-whitelist.xml	=>	WEB-INF/security/order-whitelist.xml
